uint hash(inout uint x) {
    x ^= x >> 16;
    x *= 0x7feb352dU;
    x ^= x >> 15;
    x *= 0x846ca68bU;
    x ^= x >> 16;
    return x;
}

float randomFloat(inout uint state) {
    return float(hash(state)) / 4294967296.0;
}

vec2 randomDir(inout uint state) {
    float angle = randomFloat(state) * 6.28318530718;
    float radius = sqrt(randomFloat(state));
    return vec2(cos(angle), sin(angle)) * radius;
}

#define RADIUS 15.0
#define NUM_SAMPLES 45
#define ADAPT 1.0 //for testing
#define SOBEL 1 // for testing

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;

    vec3 originalValue = texture(iChannel0, uv).rgb;
    vec3 currentValue = texture(iChannel1, uv).rgb;

    if (iFrame <= 1) {
        fragColor = vec4(originalValue, 1.0);
        return;
    }

    // Compute local gradient magnitude using Sobel approximation
    float Gx = texture(iChannel1, uv + vec2(1, 0) / iResolution.xy).r - 
               texture(iChannel1, uv - vec2(1, 0) / iResolution.xy).r;
    float Gy = texture(iChannel1, uv + vec2(0, 1) / iResolution.xy).r - 
               texture(iChannel1, uv - vec2(0, 1) / iResolution.xy).r;
    float gradientMagnitude = length(vec2(Gx, Gy)) * ADAPT;

    // Adapt parameters based on local contrast
    float K = mix(0.05, 0.2, smoothstep(0.0, 0.2, gradientMagnitude)); // Adaptive edge threshold
    float LAMBDA = mix(0.02, 0.15, 1.0 - smoothstep(0.0, 0.2, gradientMagnitude)); // Less diffusion at edges
    float GAMMA = mix(0.05, 0.04, 1.0 - smoothstep(0.0, 0.2, gradientMagnitude)); // Less pull to original in details (to experiment)

    uint state = uint(fragCoord.x + fragCoord.y * iResolution.x + iTime * 1000.0);
    vec3 diffusionSum = vec3(0.0);
    float totalWeight = 0.0;

    for (int i = 0; i < NUM_SAMPLES; i++) {
        vec2 offset = randomDir(state) * RADIUS / iResolution.xy;
        vec2 sampleUV = uv + offset;

        if (sampleUV.x < 0.0 || sampleUV.x > 1.0 || sampleUV.y < 0.0 || sampleUV.y > 1.0)
            continue;

        vec3 neighborValue = texture(iChannel1, sampleUV).rgb;
        float sampleGradient = length(neighborValue - currentValue);
        float c = exp(- (sampleGradient * sampleGradient) / (K * K));

        diffusionSum += c * (neighborValue - currentValue);
        totalWeight += c;
    }

    if (totalWeight > 0.0) {
        diffusionSum /= totalWeight;
    }

    vec3 newValue = currentValue + LAMBDA * diffusionSum + GAMMA * (originalValue - currentValue);
    newValue = clamp(newValue, 0.0, 1.0);

    fragColor = vec4(newValue, 1.0);
}

