# define NOISEAMP 0.15 //default 0.15

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec2 position = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 originalTexture = texture(iChannel0, uv).rgb;
    float noiseAmplitude = NOISEAMP;

    vec3 f = originalTexture + noiseAmplitude * (texture(iChannel2, position).rgb - 0.5);

    fragColor = vec4(f, 1.0);
}
